# Generate K_{6,7}
n = 13
partA = list(range(0, 6))
partB = list(range(6, 13))

edges = []
for u in partA:
    for v in partB:
        edges.append((u, v))

print("Number of edges:", len(edges))

# Verify triangle-free
adj = {i: set() for i in range(n)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

def has_triangle():
    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[i] & adj[j]:
                    if k > j:
                        return True
    return False

print("Triangle-free:", not has_triangle())

# Verify maximal: adding any non-edge creates triangle
def is_maximal():
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                # try adding edge (u,v)
                # check if it creates triangle: need common neighbor
                common = adj[u] & adj[v]
                if not common:
                    return False, (u,v)
    return True, None

maximal, missing = is_maximal()
print("Maximal:", maximal)
if not maximal:
    print("Missing edge that could be added:", missing)

# Print edges as list
print(edges[:10], "...")
